\section{Introduction}

\subsection{The prime point cloud}
Let $p_1=2<p_2=3<p_3=5<\cdots$ be the primes and let
\[
  P(n) = p_{n+1}\in\RR,\qquad n=0,1,2,\dots
\]
be the \emph{prime point cloud}: the $n$-th prime (zero-based) regarded as a point on the
real line. Since the enumeration of primes is strictly increasing, $P:\NN\to\RR$ is
strictly monotone.

Persistent homology asks how the topology of a point cloud varies with resolution. Fix a
scale $\eps\ge 0$ and form the \emph{Vietoris--Rips complex} $R_\eps$, whose vertices are
the indices and in which a finite set spans a simplex iff all pairwise distances are at
most $\eps$. Increasing $\eps$ yields a filtration; each homological feature is born and
dies at definite scales, and the multiset of these intervals is the \emph{barcode}.

The heuristic tested here is the following, in wide informal circulation.

\begin{conjecture}[Poisson heuristic for the prime barcode]
Near $x$ primes have density $1/\log x$, so the $H_0$ barcode of the prime cloud should
resemble that of a Poisson process of that intensity: \emph{(i)} $H_0$ bar lengths are
exponentially distributed with mean $\approx\log x$; \emph{(ii)} $H_1$ bars appear at scale
$\approx(\log x)^2$, the longest persisting from $\eps=2$ to $\infty$ and encoding the Twin
Prime Conjecture.
\end{conjecture}

We prove (i) and (ii) both false, in strong forms, and identify the true statements
replacing them.

\subsection{Summary of results}
Quantisation (Theorem~\ref{thm:quant}); refutation of the exponential law
(Theorem~\ref{thm:refute}); robustness (Theorem~\ref{thm:robust}); arbitrarily long bars
(Theorem~\ref{thm:long}); even Betti staircase and inversion
(Theorems~\ref{thm:staircase},~\ref{thm:inversion}); the Betti-area identity
(Theorem~\ref{thm:area}); twin primes as a Betti step (Theorem~\ref{thm:twin});
chordality (Theorem~\ref{thm:chord}); vanishing of $H_1$ (Theorem~\ref{thm:vanish});
exclusion of adjacent twin bars (Theorems~\ref{thm:mod3},~\ref{thm:excl}); block
divisibility (Theorem~\ref{thm:block}); completeness (Theorem~\ref{thm:complete}).

\section{Definitions and the zero-dimensional dictionary}

Throughout, $p:\NN\to\RR$ denotes an arbitrary strictly increasing point cloud on the line,
and $P$ the prime cloud.

\begin{definition}[Rips adjacency and connectivity]
For $\eps\in\RR$, indices $a,b$ are \emph{$\eps$-adjacent} if $|p(a)-p(b)|\le\eps$, and
\emph{$\eps$-connected} ($a\sim_\eps b$) if related by the reflexive--transitive closure of
$\eps$-adjacency.
\end{definition}

\begin{definition}[Bars and gaps]
For the prime cloud set $g_i = P(i+1)-P(i) = p_{i+2}-p_{i+1}$, the $i$-th \emph{prime gap}.
\end{definition}

\begin{definition}[Betti curve]
$b_0(\eps,n)$ is the number of $\eps$-connected components of $p(0),\dots,p(n)$, i.e.\ the
zeroth Betti number of the truncated Rips complex at scale $\eps$.
\end{definition}

\begin{proposition}[Line dictionary]\label{prop:dict}
Let $p$ be strictly increasing, $\eps\ge0$ and $i\le j$. Then $i\sim_\eps j$ if and only if
$p(k+1)-p(k)\le\eps$ for every $k$ with $i\le k<j$. Consequently
\[
  b_0(\eps,n) \;=\; 1+\#\{\,i<n:\ p(i+1)-p(i)>\eps\,\},
\]
and the finite $H_0$ barcode of $p(0),\dots,p(n)$ is the multiset of bars
$[0,\,p(i+1)-p(i))$ for $i<n$, together with one infinite bar.
\end{proposition}

\begin{proof}[Proof sketch]
($\Rightarrow$) Each step $|p(a)-p(b)|\le\eps$ of an $\eps$-path straddling an intermediate
consecutive pair bounds that pair's gap by $\eps$, by monotonicity. ($\Leftarrow$) If all
intermediate gaps are $\le\eps$, the chain $i\to i+1\to\cdots\to j$ realises the
connection. The components are therefore the maximal runs of consecutive indices with
internal gaps $\le\eps$, separated by the gaps exceeding $\eps$; each run merges with its
right-hand neighbour exactly when $\eps$ reaches the separating gap.
\end{proof}

Thus in dimension zero the topology of a line point cloud is exactly its gap data, and the
prime barcode is exactly the prime gap sequence $1,2,2,4,2,4,2,4,6,2,\dots$. We write
$\mu_n = \frac1n\sum_{i<n}\delta_{g_i}$ for the empirical bar-length measure, and
$b_0(\eps,n)-1$ for the reduced Betti number.

\section{Quantisation and the failure of the exponential law}

\begin{theorem}[Quantisation]\label{thm:quant}
$g_0=1$, and $g_i$ is even with $g_i\ge2$ for every $i\ge1$.
\end{theorem}

\begin{proof}
$g_0=3-2=1$. For $i\ge1$ both $p_{i+1},p_{i+2}\ge3$ are odd primes, so their difference is
even, and it is positive by strict monotonicity, hence $\ge2$.
\end{proof}

\begin{corollary}
$g_i=1$ iff $i=0$. For $i\ge1$ there is $k\ge1$ with $P(i+1)-P(i)=2k$; the measure $\mu_n$
is supported in $\{1\}\cup\{2,4,6,\dots\}$ for every $n$.
\end{corollary}

Write $B_n(a,b)=\#\{i<n:\ a<P(i+1)-P(i)<b\}$.

\begin{theorem}[Empty windows]\label{thm:empty}
For every $n$ and $k\ge1$, $B_n(2k,2k+2)=0$; also $B_n(0,1)=0$.
\end{theorem}

\begin{proof}
Suppose $2k<g_i<2k+2$ with $k\ge1$. If $i=0$ then $g_i=1\le 2k$, a contradiction. If
$i\ge1$ then $g_i=2a$, and $k<a<k+1$ is impossible in $\NN$. The second claim holds since
$g_i\ge1$ always.
\end{proof}

\begin{theorem}[Refutation of the exponential/Poisson law]\label{thm:refute}
Let $m>0$ and $k\ge1$. Then for every $n$,
\[
  B_n(2k,2k+2)=0,\qquad\text{while}\qquad e^{-2k/m}-e^{-(2k+2)/m}>0 .
\]
The same holds on $(0,1)$ with predicted mass $1-e^{-1/m}>0$. Hence for no mean $m$ --- in
particular not $m=\log x$ --- are the prime $H_0$ bar lengths exponentially distributed.
\end{theorem}

\begin{proof}
Vanishing is Theorem~\ref{thm:empty}. An exponential law of mean $m$ has survival function
$t\mapsto e^{-t/m}$, strictly decreasing, so the mass of $(a,b)$ with $a<b$ is
$e^{-a/m}-e^{-b/m}>0$.
\end{proof}

\begin{remark}
The refutation compares two explicitly nonvacuous quantities: a strictly positive predicted
proportion against an identically zero observed count, at every truncation. It is
structural, not statistical: $\mu_n$ is purely atomic, while every exponential law is
absolutely continuous.
\end{remark}

\begin{theorem}[Robust quantisation]\label{thm:robust}
For every $i$ and every $k\ge1$,
$\bigl|(P(i+1)-P(i))-(2k+1)\bigr|\ \ge\ 1$: every bar length is at distance at least $1$
from every odd integer $\ge3$.
\end{theorem}

\begin{proof}
If $i=0$ the length is $1$ and $|1-(2k+1)|=2k\ge2$. If $i\ge1$ the length is even, say
$2a$; then $2a\le 2k$ or $2a\ge 2k+2$, and in both cases $|2a-(2k+1)|\ge1$.
\end{proof}

Since bottleneck distance moves each bar endpoint by at most the distance itself,
Theorem~\ref{thm:robust} shows that any barcode within bottleneck distance $<1/2$ of the
prime barcode still has empty windows of positive width around every odd integer, hence is
still not exponential.

\begin{theorem}[Arbitrarily long bars]\label{thm:long}
For every $N\in\NN$ there is $i$ with $g_i\ge N$. Consequently the barcode is unbounded and
has no exponential tail at a fixed mean.
\end{theorem}

\begin{proof}
Let $m=N+2$. For $2\le j\le m$ the number $m!+j$ is divisible by $j$ and exceeds $j$, hence
is composite, so $[m!+2,\,m!+m]$ is prime-free. The prime preceding this interval and the
prime following it differ by more than $m-2=N$.
\end{proof}

\section{The Betti staircase and the area identity}

By Proposition~\ref{prop:dict}, $b_0(\eps,n)=1+\#\{i<n: g_i>\eps\}$ for the prime cloud.

\begin{theorem}[Even quantisation of the staircase]\label{thm:staircase}
Let $k\ge1$ and $2k\le\eps_1\le\eps_2<2k+2$. Then $b_0(\eps_1,n)=b_0(\eps_2,n)$ for all $n$:
the Betti curve is constant on $[2k,2k+2)$.
\end{theorem}

\begin{proof}
It suffices that $\{i<n: g_i>\eps_1\}=\{i<n: g_i>\eps_2\}$; one inclusion is monotonicity.
Conversely $g_i>\eps_1\ge2k$ excludes $i=0$ (as $g_0=1$) and forces $g_i=2a$ with
$a\ge k+1$, i.e.\ $g_i\ge 2k+2>\eps_2$.
\end{proof}

\begin{remark}
Almost surely a Poisson cloud has pairwise distinct bar lengths dense in $(0,\infty)$, so
its Betti curve is non-constant on every subinterval; the prime staircase jumps only at
even integers.
\end{remark}

\begin{lemma}[Window splitting]\label{lem:split}
For $k\ge1$ and every $n$,
$\#\{i<n: g_i>2k-1\}=\#\{i<n: g_i>2k+1\}+\#\{i<n: g_i=2k\}$.
\end{lemma}

\begin{proof}
Every $g_i$ with $i\ge1$ is even and $g_0=1$, so $g_i>2k-1$ holds iff $g_i>2k+1$ or
$g_i=2k$, disjointly.
\end{proof}

\begin{theorem}[Inversion formula]\label{thm:inversion}
For $k\ge1$,
\[
  \#\{\,i<n:\ g_i=2k\,\} \;=\; b_0(2k-1,\,n)-b_0(2k+1,\,n).
\]
Hence the Betti staircase and the prime-gap histogram determine one another.
\end{theorem}

\begin{proof}
Immediate from Proposition~\ref{prop:dict} and Lemma~\ref{lem:split}.
\end{proof}

\begin{theorem}[Betti area identity]\label{thm:area}
For every $n$,
\[
  \int_0^{\infty}\bigl(b_0(\eps,n)-1\bigr)\,d\eps \;=\; p_{n+1}-2 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Layer-cake: for $\eps>0$,
$b_0(\eps,n)-1=\#\{i<n: g_i>\eps\}=\sum_{i<n}\mathbf 1_{(0,g_i)}(\eps)$, since the $i$-th
bar contributes exactly while the scale is below its length. Each indicator has bounded
support, hence is integrable, so the integral passes through the finite sum, and
$\int_0^\infty \mathbf 1_{(0,g_i)}=g_i$. Finally $\sum_{i<n}g_i=p_{n+1}-p_1=p_{n+1}-2$ by
telescoping.
\end{proof}

\begin{corollary}[Mean bar length]
For $n\ge1$ the average of the first $n$ bar lengths is
$\frac1n\int_0^\infty(b_0(\eps,n)-1)\,d\eps=(p_{n+1}-2)/n$, the exact form of the average
prime gap whose asymptotics the Prime Number Theorem describes as $\sim\log p_n$. The Betti
area diverges with $n$.
\end{corollary}

For the primes below $10^6$ ($78\,497$ finite bars) the identity gives area
$999\,981=999\,983-2$, and the mean bar length is $12.739$ against $\log p_n=13.815$.

\section{The Twin Prime Conjecture is a Betti step}

\begin{definition}
The \emph{twin step} is $\tau(n)=b_0(1,n)-b_0(2,n)$, the number of components merging as
the scale crosses $2$.
\end{definition}

\begin{theorem}[Twin primes live in $H_0$]\label{thm:twin}
For every $n$, $\tau(n)=\#\{i<n:\ g_i=2\}$. Consequently there are infinitely many twin
primes if and only if $\tau$ is unbounded, i.e.\ $\forall N\,\exists n:\ \tau(n)\ge N$.
\end{theorem}

\begin{proof}
$b_0(1,n)-b_0(2,n)=\#\{i<n:g_i>1\}-\#\{i<n:g_i>2\}$, and since gaps are integers
$\{g_i>1\}$ splits disjointly into $\{g_i>2\}$ and $\{g_i=2\}$. A predicate holds
infinitely often iff its counting function over initial segments is unbounded: any $N$
witnesses lie in some initial segment, and conversely a finite witness set caps the counts.
Finally $g_i=2$ infinitely often is exactly the twin prime statement.
\end{proof}

\section{Vanishing of $H_1$ for point clouds on a line}

\subsection{The combinatorial statement}

\begin{theorem}[Chordality]\label{thm:chord}
Let $p$ be strictly increasing, $\eps\in\RR$, and let $c:\NN\to\NN$ be a closed cycle of
length $k\ge4$ in the Rips graph at scale $\eps$: $k$-periodic, injective on one period,
with $|p(c(i))-p(c(i+1))|\le\eps$ for all $i$. Then there is $t$ with $c(t)\ne c(t+2)$ and
$|p(c(t))-p(c(t+2))|\le\eps$: the cycle has a chord between vertices at cyclic distance
exactly $2$.
\end{theorem}

\begin{proof}
Let $v=c(i_0)$ minimise $p\circ c$ over one period; by periodicity $p(v)\le p(c(i))$ for all
$i$. Choose $t$ with $t+1\equiv i_0$, so $c(t)$ and $c(t+2)$ are the cycle neighbours of
$v$. Both lie in $[p(v),\,p(v)+\eps]$, hence within $\eps$ of each other. Injectivity on a
period with $k\ge4$ gives $c(t)\ne c(t+2)$, since equality would force $k\mid2$.
\end{proof}

\begin{corollary}
At every scale the Rips graph of the prime point cloud is chordal: it contains no induced
cycle of length $\ge4$. The statement is not vacuous --- at scale $4$ the primes $3,5,7$
span a triangle.
\end{corollary}

\subsection{The homological statement over $\FF_2$}

\begin{definition}[$\FF_2$ one-chains]
An \emph{edge} is an ordered pair $e=(a,b)$ with $a<b$; it is a \emph{Rips edge at scale
$\eps$} if $|p(a)-p(b)|\le\eps$. A \emph{one-chain} is a finite set $E$ of edges, addition
being symmetric difference $\sd$. The degree $\deg_E(v)$ is the number of edges of $E$
incident to $v$; $\partial_1E$ is the set of odd-degree vertices, so $E$ is a \emph{cycle}
iff all degrees are even. For $a<b<c$ the \emph{triangle chain} is
$T(a,b,c)=\{(a,b),(b,c),(a,c)\}$, a \emph{Rips triangle} if all three edges are Rips edges.
The \emph{triangle span} is the set of chains obtained from $\emptyset$ by repeatedly adding
Rips triangles; it is exactly $\operatorname{im}\partial_2$ of the flag complex.
\end{definition}

Since $H_1=\ker\partial_1/\operatorname{im}\partial_2$, vanishing of $H_1$ means precisely
that every cycle lies in the triangle span.

\begin{theorem}[Vanishing of $H_1$ on a line]\label{thm:vanish}
Let $p:\NN\to\RR$ be strictly increasing and $\eps\in\RR$. Every $\FF_2$ one-cycle $E$ all
of whose edges are Rips edges at scale $\eps$ lies in the span of the Rips triangles at
scale $\eps$. Consequently $H_1(R_\eps;\FF_2)=0$ for every $\eps$.
\end{theorem}

\begin{proof}
Define the weight $\mu(E)=\sum_{(a,b)\in E}b$ and induct strongly on $\mu(E)$.

If $E=\emptyset$ it lies in the span. Otherwise let $v$ be the largest right endpoint
occurring in $E$; every edge incident to $v$ has $v$ as its right endpoint, since an edge
$(v,b)$ would have $b>v$. The degree of $v$ is nonzero and even, hence $\ge2$: there are
distinct $(u,v),(w,v)\in E$, named so that $u<w<v$.

\emph{The chord is present.} As $p$ is increasing, $p(u)<p(w)<p(v)$, and
$|p(u)-p(v)|\le\eps$ gives $p(v)-p(u)\le\eps$; hence $0<p(w)-p(u)<p(v)-p(u)\le\eps$, so
$(u,w)$ is a Rips edge and $T=T(u,w,v)$ is a Rips triangle.

\emph{The move preserves cycles.} Every vertex has degree $0$ or $2$ in $T$, so $T$ is a
cycle, and $\deg_{A\sd B}(x)\equiv\deg_A(x)+\deg_B(x)\pmod 2$. Hence $E'=T\sd E$ is a cycle
whose edges are all Rips edges.

\emph{The move terminates.} Weights satisfy
$\mu(A\sd B)+2\sum_{e\in A\cap B}e_2=\mu(A)+\mu(B)$. Here $\mu(T)=w+2v$ and
$\{(u,v),(w,v)\}\subseteq T\cap E$, so $\sum_{e\in T\cap E}e_2\ge 2v$, giving
\[
  \mu(E') \;=\; \mu(T)+\mu(E)-2\!\!\sum_{e\in T\cap E}\!\! e_2
  \;\le\; (w+2v)+\mu(E)-4v \;=\; \mu(E)+(w-2v) \;<\; \mu(E),
\]
since $0\le w<v$. Concretely, two edges of weight $v$ are deleted and at most one new edge,
of weight $w<v$, appears.

By induction $E'$ lies in the triangle span, and $E=T\sd E'$ because $\sd$ is an
involution; hence $E$ lies in the span.
\end{proof}

\begin{corollary}
The prime point cloud has vanishing first homology at every scale. In particular the
conjectured $H_1$ bars at scale $(\log x)^2$ do not exist, and there is no ``twin prime
$H_1$ bar'' persisting from $\eps=2$ to $\infty$.
\end{corollary}

\begin{example}[Non-vacuity]
At scale $\eps=8$ the quadrilateral on the primes $3,5,7,11$,
$E=\{(3,5),(5,7),(7,11),(3,11)\}$, has all degrees $2$ and is a nonzero chain, hence an
honest one-cycle; and $E=T(3,5,7)\sd T(3,7,11)$, both summands being Rips triangles at
scale $8$ (their longest edges are $4$ and $8$). The cycle exists; the hole does not.
\end{example}

\begin{remark}
The mechanism is dimensional, not arithmetic: a cloud in $\RR^1$ has an indifference graph,
whose extremal cycle vertex sees both neighbours inside one window of width $\eps$, so they
see each other. Nontrivial $H_1$ would require an embedding into dimension $\ge2$.
\end{remark}

\section{Correlations: the barcode is not an independent process}

\begin{theorem}[Mod-$3$ law]\label{thm:mod3}
For every $i\ge2$, at least one of $g_i$, $g_{i+1}$, $g_i+g_{i+1}$ is divisible by $3$.
Consequently if $g_i=g_{i+1}=d$ with $i\ge2$, then $3\mid d$.
\end{theorem}

\begin{proof}
The primes $p_{i+1}<p_{i+2}<p_{i+3}$ all exceed $3$, so each residue mod $3$ lies in
$\{1,2\}$; two coincide, and the corresponding difference is $g_i$, $g_{i+1}$ or
$g_i+g_{i+1}$. If $g_i=g_{i+1}=d$ then $3\mid d$ or $3\mid 2d$, and in both cases $3\mid d$.
\end{proof}

\begin{theorem}[Exclusion of adjacent equal short bars]\label{thm:excl}
For $i\ge2$ it is never the case that $g_i=g_{i+1}=2$, nor that $g_i=g_{i+1}=4$. Hence
$\#\{i<n:\ i\ge2,\ g_i=2,\ g_{i+1}=2\}=0$ for every $n$. The hypothesis $i\ge2$ is
necessary and sharp: $g_1=g_2=2$, from the triple $3,5,7$, the unique adjacent twin pair in
the entire barcode.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:mod3} would force $3\mid2$, respectively $3\mid4$.
\end{proof}

\begin{corollary}[Refutation of independence]
A model positing independent bar lengths with $\mathbb P(\text{length}=2)=q>0$ predicts
$(n-1)q^2>0$ adjacent twin-bar pairs among the first $n$ bars, whereas the prime barcode
contains none past the start. The prime barcode is therefore not an independent-increment
(Poisson) process.
\end{corollary}

\begin{theorem}[Block divisibility]\label{thm:block}
Let $q$ be prime and let $i$ satisfy $p_{i+1}>q$. Then there exist $j<k<q$ with
\[
  q \ \Bigm|\ \sum_{m=j}^{k-1} g_{i+m}.
\]
\end{theorem}

\begin{proof}
The $q$ primes $p_{i+1},\dots,p_{i+q}$ all exceed $q$, so their residues mod $q$ lie in the
$q-1$ classes $\{1,\dots,q-1\}$; by pigeonhole two coincide, at indices $i+j$ and $i+k$ with
$j<k<q$. Their difference is divisible by $q$, and telescoping gives
$p_{i+k+1}-p_{i+j+1}=\sum_{m=j}^{k-1}g_{i+m}$.
\end{proof}

\begin{corollary}[No long constant runs]
Let $q$ be prime, $p_{i+1}>q$, and suppose $g_{i+m}=d$ for all $m<q-1$. Then $q\mid d$.
In particular, past $p=5$ there is no run of four consecutive bars of length $2$: no five
primes in arithmetic progression with common difference $2$.
\end{corollary}

\begin{proof}
The block sum of Theorem~\ref{thm:block} is $(k-j)d$ with $0<k-j<q$; primality of $q$ gives
$q\mid d$. For the special case, $q=5$ would force $5\mid2$.
\end{proof}

\begin{theorem}[Cap on the twin step]
For every $n$, $\tau(n)\le\lfloor n/2\rfloor+3$.
\end{theorem}

\begin{proof}
$\tau(n)=|S|$ with $S=\{i<n:g_i=2\}$, and by Theorem~\ref{thm:excl} $S$ contains no two
consecutive integers $\ge2$. Discard $\{0,1\}$; on the rest $i\mapsto\lfloor i/2\rfloor$ is
injective (two indices with equal halves differ by $1$, which is forbidden) into
$\{0,\dots,\lfloor n/2\rfloor\}$.
\end{proof}

No i.i.d.\ model obeys such a deterministic constraint.

\medskip
\noindent\textbf{Empirical corroboration.} Among the $78\,497$ bars below $10^6$: the
adjacent pattern $(2,2)$ occurs exactly once (at $3,5,7$); $(4,4)$ and $(8,8)$ never occur;
the repeats that do occur are $(6,6)$ with $1\,929$ occurrences and
$(12,12),(18,18),(24,24),(30,30),(36,36),(42,42)$ --- all multiples of $3$, exactly as
Theorem~\ref{thm:mod3} requires; mixed patterns are common, e.g.\ $(2,4)$ with $1\,393$ and
$(4,2)$ with $1\,444$ occurrences.

\section{The barcode is a complete invariant}

\begin{theorem}[Reconstruction]\label{thm:complete}
For every $n$, $p_{n+1}=2+\sum_{m<n}g_m$.
\end{theorem}

\begin{proof}
Telescoping: $\sum_{m<n}(p_{m+2}-p_{m+1})=p_{n+1}-p_1$.
\end{proof}

Hence the persistence diagram of the prime point cloud determines the primes: every
arithmetic statement about primes is a statement about the barcode, which explains both the
abundance of structure in the barcode and the failure of any genericity assumption.

\section{Algorithms}

\textbf{A. Barcode extraction.} Sieve to $x$ in $O(x\log\log x)$; the barcode is the list of
consecutive differences, in $O(\pi(x))$. Correctness is Proposition~\ref{prop:dict}.

\smallskip
\noindent\textbf{B. Betti curve and inversion.} From the histogram
$h(2k)=\#\{i<n:g_i=2k\}$, $b_0(\eps,n)=1+\sum_{2k>\eps}h(2k)$, obtained for all even
thresholds by one suffix sum in $O(g_{\max})$. Theorem~\ref{thm:inversion} makes
$h\leftrightarrow b_0$ a bijection computed by prefix/suffix differencing.

\smallskip
\noindent\textbf{C. Cycle reduction (constructive vanishing of $H_1$).} Given $\eps$, a
strictly increasing cloud and a set $E$ of Rips edges with all degrees even, repeatedly:
take the maximal vertex $v$ carried by $E$; take the two smallest left endpoints $u<w$ among
the edges $(\cdot,v)\in E$; emit $T(u,w,v)$; replace $E$ by $T\sd E$. By the proof of
Theorem~\ref{thm:vanish} each step is legal, preserves the cycle condition and strictly
decreases $\mu(E)$, so the loop terminates in at most $\mu(E)$ iterations and outputs an
explicit triangle decomposition certifying that the cycle bounds.

\section{Discussion}

\subsection{What survives of the Poisson heuristic}
Nothing above contradicts the Cramér-style heuristic as an asymptotic guide: the mean bar
length $(p_n-2)/n$ does track $\log p_n$. What fails is its description of the barcode at
fine scales, exactly where arithmetic lives: divisibility by $2$ quantises the bar lengths,
destroying absolute continuity; divisibility by $3$ creates repulsion between $\eps=2$
merges, destroying independence; divisibility by each prime $q$ imposes a block law. A
corrected model must be a quantised, congruence-constrained point process --- morally the
Hardy--Littlewood singular-series model --- and the theorems above are precisely the
deterministic constraints it must respect.

\subsection{Why $H_1$ was never available}
The conjecture that $H_1$ should encode twin primes was a category error of dimension. The
prime cloud lives in $\RR^1$, whose Rips complexes are flag complexes of indifference
graphs, and Theorem~\ref{thm:vanish} shows those have no first homology at any scale. The
arithmetic is forced into $H_0$, where Theorem~\ref{thm:twin} locates it precisely: at the
first step of the staircase. The same theorem indicates where a genuine $H_1$ theory could
live --- in embeddings of the primes into dimension $\ge2$.

\subsection{Interpretation of the area identity}
Theorem~\ref{thm:area} says that total persistence and the Betti curve are the same datum
seen twice, and that the datum is arithmetic. It is a translation device: the Prime Number
Theorem becomes the assertion that the normalised Betti area is asymptotic to $\log p_n$,
and large-gap results become statements about the support of the staircase.

\section{Future directions}

\begin{conjecture}[C1: admissibility is the only obstruction]
Call a tuple $(d_1,\dots,d_k)$ of positive even integers \emph{barcode-admissible} if for
every prime $q\le k+1$ the partial sums $0,d_1,d_1+d_2,\dots,d_1+\cdots+d_k$ do not cover
all residues mod $q$. Then a pattern occurs as $k$ consecutive bars of the prime barcode,
infinitely often, if and only if it is barcode-admissible.
\end{conjecture}

The ``only if'' half is proved here: Theorem~\ref{thm:block} shows a non-admissible pattern
occurs at most finitely often, and its constant-pattern corollary is the special case. The
existence half is a barcode restatement of the Hardy--Littlewood/Dickson prime $k$-tuple
conjecture. The key insight is that the $q=3$ exclusion behind Theorem~\ref{thm:excl} is not
a curiosity but the shadow of a complete residue-theoretic classification: the pigeonhole on
prime residues mod $q$ gives exactly the covering condition, so realisable local barcode
patterns are cut out by finitely many congruence conditions.

\medskip
\noindent\textbf{C2. Betti-area asymptotics.} Make the equivalence of
Theorem~\ref{thm:area} quantitative: relate error terms in the Prime Number Theorem to
convergence rates of the normalised Betti area and to the shape of the staircase near
$\eps\approx\log p_n$.

\smallskip
\noindent\textbf{C3. Higher-dimensional embeddings.} Determine which planar embeddings ---
e.g.\ $n\mapsto(p_n\bmod a,\ p_n\bmod b)$, or spiral embeddings --- produce nontrivial
persistent $H_1$, and whether the resulting bars have arithmetic meaning.

\smallskip
\noindent\textbf{C4. Stability and inverse problems.} Determine the exact bottleneck radius
within which no absolutely continuous model fits, and classify quantised,
congruence-constrained processes whose barcodes lie within a prescribed bottleneck distance
of the prime barcode.

\smallskip
\noindent\textbf{C5. Sharpening the twin-step cap.} The cap $\tau(n)\le n/2+3$ should be
improvable using higher moduli; conjecturally $\tau(n)\sim 2\Pi_2\,n/\log p_n$ with $\Pi_2$
the twin prime constant.

\section{Conclusion}

The primes, laid on the real line, do have a topology, and it is entirely zero-dimensional.
Their barcode is the sequence of prime gaps: atomic on $\{1\}\cup2\NN$, with hard empty
windows no exponential law can respect; heavy-tailed, with bars of arbitrarily large length;
correlated, with $3$-divisibility forbidding adjacent equal bars and every prime $q$
imposing a block law; complete, reconstructing the primes exactly; and calibrated, with area
$p_n-2$ under its reduced Betti curve. In dimension one there is nothing: every cycle in the
Rips complex of a line point cloud is a sum of triangles, so the conjectured twin-prime hole
does not exist. The Twin Prime Conjecture is present in the barcode nonetheless, in an
unexpectedly plain form --- as the assertion that the single Betti step at scale $\eps=2$
grows without bound.

